"use client";

import * as React from "react";
import { Archive, Bell, X } from "lucide-react";
import { NumberRoll } from "./number-roll";
import { RelativeTime, toTime, type DateLike } from "./relative-time";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import { useRowMotion } from "./use-row-motion";

/* ─────────────────────────────────────────────────────────
 * NOTIFICATION INBOX: the bell, done properly
 *
 *   arrive    a new notification rings the bell (a short swing
 *             from its top) and the count rolls; if the inbox is
 *             open it fades in on top while the rest glide down
 *   open      the bell's own circle grows into the inbox: size
 *             and corners ease, the bell fades into the list,
 *             and it folds back the same way
 *   tabs      Unread / All, the highlight sliding between them;
 *             Unread counts as you go
 *   read      opening a notification reads it; the dot shrinks,
 *             the title settles to grey, and in Unread the row
 *             folds away a moment later. Mark all read does
 *             them together
 *   archive   the row folds away and the rest glide up
 *   empty     "You're all caught up", with a drawn check
 *
 * Items are plain records; subscribe() feeds new ones from
 * Knock, Novu, Supabase Realtime or your own stream.
 * ───────────────────────────────────────────────────────── */

export type { DateLike };

export interface InboxItem {
  id: string;
  title: string;
  body?: string;
  at: DateLike;
  read?: boolean;
  actor?: { name: string; image?: string };
  /** Where opening it goes. */
  href?: string;
}

export interface NotificationInboxProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "defaultValue" | "onChange"
> {
  value?: InboxItem[];
  defaultValue?: InboxItem[];
  onValueChange?: (items: InboxItem[]) => void;
  /** Feeds new notifications: call push with one or many; return a function that stops it. */
  subscribe?: (push: (items: InboxItem | InboxItem[]) => void) => () => void;
  /** Saves read state. Throw to put it back. */
  onRead?: (ids: string[], read: boolean) => Promise<unknown> | unknown;
  onArchive?: (ids: string[]) => Promise<unknown> | unknown;
  /** Called when a notification is opened (after it's marked read). */
  onOpen?: (item: InboxItem) => void;
  /** Older notifications, newest first; an empty list means there are no more. */
  loadMore?: (before: InboxItem) => Promise<InboxItem[]>;
  /** Which edge of the bell the inbox lines up with. */
  align?: "end" | "start";
  label?: string;
  defaultOpen?: boolean;
}

type Phase = "closed" | "opening" | "open" | "closing";

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const DURATION = 460;
const WIDTH = 384;
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const NONE: InboxItem[] = [];

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const DAY = 86_400_000;
const groupOf = (at: DateLike) => {
  const t = new Date(toTime(at));
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const start = today.getTime();
  return t.getTime() >= start
    ? "Today"
    : t.getTime() >= start - DAY
      ? "Yesterday"
      : "Earlier";
};

function Avatar({ item }: { item: InboxItem }) {
  if (item.actor?.image)
    return (
      <img
        src={item.actor.image}
        alt=""
        className="size-7 shrink-0 rounded-full object-cover shadow-[0_0_0_1px_var(--border)]"
      />
    );
  const letters = (item.actor?.name ?? "•")
    .split(/\s+/)
    .slice(0, 2)
    .map((w) => w[0]?.toUpperCase())
    .join("");
  return (
    <span
      aria-hidden="true"
      className="grid size-7 shrink-0 place-items-center rounded-full bg-muted text-[10.5px] font-medium text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]"
    >
      {letters}
    </span>
  );
}

interface RowProps {
  item: InboxItem;
  reduced: boolean;
  canArchive: boolean;
  act: React.RefObject<{
    open: (i: InboxItem) => void;
    read: (i: InboxItem, read: boolean) => void;
    archive: (i: InboxItem) => void;
  }>;
}

const Row = React.memo(function Row({
  item,
  reduced,
  canArchive,
  act,
}: RowProps) {
  const unread = !item.read;
  const Body = item.href ? "a" : "button";
  return (
    <li data-row-id={item.id} className="group relative">
      <Body
        {...(item.href ? { href: item.href } : { type: "button" as const })}
        onClick={() => act.current.open(item)}
        className={`flex w-full cursor-pointer items-start gap-3 rounded-[12px] px-3 py-2.5 pr-16 text-left transition-colors hover:bg-accent/60 ${FOCUS}`}
      >
        <span className="relative mt-0.5">
          <Avatar item={item} />
        </span>
        <span className="min-w-0 flex-1">
          <span
            className={`block text-[13px] leading-[1.4] transition-colors duration-500 ${unread ? "font-medium text-foreground" : "text-muted-foreground"}`}
          >
            {item.title}
            <span className="sr-only">{unread ? ", unread" : ""}</span>
          </span>
          {item.body && (
            <span className="mt-0.5 line-clamp-2 block text-[12px] leading-[1.45] text-muted-foreground">
              {item.body}
            </span>
          )}
          <span className="mt-1 block text-[11px] text-muted-foreground">
            <RelativeTime date={item.at} />
          </span>
        </span>
      </Body>
      {/* The unread dot doubles as the read / unread toggle; archive sits beside it. */}
      <span className="absolute top-2.5 right-2 flex items-center gap-0.5">
        {canArchive && (
          <button
            type="button"
            aria-label={`Archive “${item.title}”`}
            onClick={() => act.current.archive(item)}
            className={`grid size-7 cursor-pointer place-items-center rounded-full text-muted-foreground opacity-0 transition-[opacity,background-color,color] group-focus-within:opacity-100 group-hover:opacity-100 hover:bg-accent hover:text-foreground [@media(pointer:coarse)]:opacity-100 ${FOCUS}`}
          >
            <Archive
              className="size-3.5"
              strokeWidth={1.75}
              aria-hidden="true"
            />
          </button>
        )}
        <button
          type="button"
          aria-label={
            unread ? `Mark “${item.title}” read` : `Mark “${item.title}” unread`
          }
          aria-pressed={!unread}
          onClick={() => act.current.read(item, unread)}
          className={`grid size-7 cursor-pointer place-items-center rounded-full transition-colors hover:bg-accent ${FOCUS}`}
        >
          <span
            aria-hidden="true"
            className={`size-2 rounded-full transition-[transform,background-color,box-shadow] ${unread ? "bg-primary" : "bg-transparent shadow-[inset_0_0_0_1px_var(--border)] group-hover:shadow-[inset_0_0_0_1px_var(--muted-foreground)]"}`}
            style={{
              transform: unread ? "scale(1)" : "scale(0.8)",
              transitionDuration: reduced ? "0ms" : "420ms",
              transitionTimingFunction: EASE,
            }}
          />
        </button>
      </span>
    </li>
  );
});

export function NotificationInbox({
  value,
  defaultValue = NONE,
  onValueChange,
  subscribe,
  onRead,
  onArchive,
  onOpen,
  loadMore,
  align = "end",
  label = "Inbox",
  defaultOpen = false,
  className = "",
  ...props
}: NotificationInboxProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [inner, setInner] = React.useState(defaultValue);
  const items = value ?? inner;
  const [phase, setPhase] = React.useState<Phase>(
    defaultOpen ? "open" : "closed",
  );
  const [tab, setTab] = React.useState<"unread" | "all">("unread");
  const [leaving, setLeaving] = React.useState<string[]>([]);
  const [markAll, setMarkAll] = React.useState<ActionStatus>("idle");
  const [loading, setLoading] = React.useState(false);
  const [noMore, setNoMore] = React.useState(!loadMore);
  const [panelHeight, setPanelHeight] = React.useState(0);
  const [fit, setFit] = React.useState({ width: WIDTH, shift: 0 });
  const [announce, setAnnounce] = React.useState("");
  const [bar, setBar] = React.useState({ left: 0, width: 0, ready: false });
  const wrapRef = React.useRef<HTMLDivElement>(null);
  const bellRef = React.useRef<HTMLButtonElement>(null);
  const iconRef = React.useRef<HTMLSpanElement>(null);
  const panelRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLUListElement>(null);
  const ghostRef = React.useRef<HTMLDivElement>(null);
  const tabRefs = React.useRef<Record<string, HTMLButtonElement | null>>({});
  const timer = React.useRef(0);
  const latest = React.useRef(items);
  React.useLayoutEffect(() => {
    latest.current = items;
  });
  const expanded = phase === "open";
  const mounted = phase !== "closed";

  const commit = React.useCallback(
    (next: InboxItem[]) => {
      if (value === undefined) setInner(next);
      onValueChange?.(next);
    },
    [value, onValueChange],
  );

  const unreadCount = items.filter((i) => !i.read).length;
  const shown = items.filter(
    (i) => tab === "all" || !i.read || leaving.includes(i.id),
  );
  const rows: (
    { kind: "head"; key: string } | { kind: "item"; item: InboxItem }
  )[] = [];
  let lastGroup = "";
  for (const item of shown) {
    const g = groupOf(item.at);
    if (g !== lastGroup) rows.push({ kind: "head", key: `head-${g}` });
    lastGroup = g;
    rows.push({ kind: "item", item });
  }
  const ranks = new Map(
    rows.map((r, i) => [r.kind === "head" ? r.key : r.item.id, i]),
  );
  useRowMotion(listRef, { reduced, ranks, ghosts: ghostRef, resetKey: tab });

  // New notifications: the bell swings, the count rolls.
  const ring = React.useCallback(() => {
    if (reduced) return;
    iconRef.current?.animate(
      [
        { transform: "rotate(0deg)" },
        { transform: "rotate(-16deg)" },
        { transform: "rotate(13deg)" },
        { transform: "rotate(-8deg)" },
        { transform: "rotate(4deg)" },
        { transform: "rotate(0deg)" },
      ],
      { duration: 720, easing: "ease-out" },
    );
  }, [reduced]);

  React.useEffect(() => {
    if (!subscribe) return;
    return subscribe((incoming) => {
      const list = Array.isArray(incoming) ? incoming : [incoming];
      const fresh = list.filter(
        (n) => !latest.current.some((i) => i.id === n.id),
      );
      if (!fresh.length) return;
      commit([...fresh, ...latest.current]);
      ring();
      setAnnounce(
        fresh.length === 1
          ? `New: ${fresh[0].title}`
          : `${fresh.length} new notifications`,
      );
    });
  }, [subscribe, commit, ring]);

  const measureFit = () => {
    const wrap = wrapRef.current;
    if (!wrap) return;
    const r = wrap.getBoundingClientRect();
    const vw = document.documentElement.clientWidth;
    const width = Math.min(WIDTH, vw - 24);
    // Lined up with the bell's edge, nudged back on screen.
    const shift =
      align === "end"
        ? Math.max(0, 12 - (r.right - width))
        : Math.min(0, vw - 12 - (r.left + width));
    setFit((f) =>
      f.width === width && f.shift === shift ? f : { width, shift },
    );
  };

  // Opened from the start: fit it to the screen before the first paint.
  React.useLayoutEffect(() => {
    if (defaultOpen) measureFit();
  }, []);

  const open = () => {
    if (phase === "open" || phase === "opening") return;
    window.clearTimeout(timer.current);
    measureFit();
    setPhase(reduced ? "open" : "opening");
  };
  const close = React.useCallback(
    (refocus = true) => {
      window.clearTimeout(timer.current);
      if (refocus) bellRef.current?.focus({ preventScroll: true });
      if (reduced) return setPhase("closed");
      setPhase("closing");
      timer.current = window.setTimeout(() => setPhase("closed"), DURATION);
    },
    [reduced],
  );

  React.useEffect(() => {
    if (phase !== "opening") return;
    let inner = 0;
    const outer = requestAnimationFrame(
      () => (inner = requestAnimationFrame(() => setPhase("open"))),
    );
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [phase]);
  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  React.useLayoutEffect(() => {
    const panel = panelRef.current;
    if (!panel) return;
    const measure = () => setPanelHeight(panel.offsetHeight);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(panel);
    return () => observer.disconnect();
  }, [mounted]);

  React.useLayoutEffect(() => {
    const b = tabRefs.current[tab];
    if (!b) return;
    setBar((p) =>
      p.left === b.offsetLeft && p.width === b.offsetWidth
        ? p
        : { left: b.offsetLeft, width: b.offsetWidth, ready: p.width > 0 },
    );
  }, [tab, mounted, unreadCount]);

  React.useEffect(() => {
    if (expanded) tabRefs.current[tab]?.focus({ preventScroll: true });
  }, [expanded]);

  React.useEffect(() => {
    if (!expanded) return;
    const onDown = (e: PointerEvent) => {
      if (!wrapRef.current?.contains(e.target as Node)) close(false);
    };
    document.addEventListener("pointerdown", onDown);
    return () => document.removeEventListener("pointerdown", onDown);
  }, [expanded, close]);

  const setRead = async (ids: string[], read: boolean) => {
    const before = latest.current;
    commit(before.map((i) => (ids.includes(i.id) ? { ...i, read } : i)));
    if (read && tab === "unread") {
      // Read rows stay a moment in Unread, then fold away.
      setLeaving((l) => [...l, ...ids]);
      window.setTimeout(
        () => setLeaving((l) => l.filter((x) => !ids.includes(x))),
        900,
      );
    }
    try {
      await onRead?.(ids, read);
    } catch {
      commit(
        latest.current.map((i) =>
          ids.includes(i.id) ? { ...i, read: !read } : i,
        ),
      );
      setAnnounce("That change couldn't be saved.");
    }
  };

  const act = React.useRef<RowProps["act"]["current"]>(null!);
  React.useLayoutEffect(() => {
    act.current = {
      open: (item) => {
        if (!item.read) setRead([item.id], true);
        onOpen?.(item);
      },
      read: (item, read) => {
        setRead([item.id], read);
        setAnnounce(read ? "Marked read." : "Marked unread.");
      },
      archive: async (item) => {
        const before = latest.current;
        commit(before.filter((i) => i.id !== item.id));
        setAnnounce("Archived.");
        try {
          await onArchive?.([item.id]);
        } catch {
          commit(
            [item, ...latest.current].sort(
              (a, b) => toTime(b.at) - toTime(a.at),
            ),
          );
          setAnnounce("That couldn't be archived.");
        }
      },
    };
  });

  const readAll = async () => {
    const ids = latest.current.filter((i) => !i.read).map((i) => i.id);
    if (!ids.length) return;
    setMarkAll("pending");
    try {
      await setRead(ids, true);
      setMarkAll("success");
      setAnnounce("All marked read.");
    } catch {
      setMarkAll("error");
    }
  };

  const more = async () => {
    const last = latest.current[latest.current.length - 1];
    if (!loadMore || !last || loading) return;
    setLoading(true);
    try {
      const older = await loadMore(last);
      if (!older.length) setNoMore(true);
      else
        commit([
          ...latest.current,
          ...older.filter((o) => !latest.current.some((i) => i.id === o.id)),
        ]);
    } finally {
      setLoading(false);
    }
  };

  const width = expanded ? fit.width : 36;
  const height = expanded ? panelHeight : 36;
  const empty = !shown.length;

  return (
    <div
      ref={wrapRef}
      className={`relative inline-flex ${className}`}
      onKeyDown={(e) => {
        if (e.key === "Escape" && expanded) {
          e.preventDefault();
          close();
        }
      }}
      {...props}
    >
      <button
        ref={bellRef}
        type="button"
        aria-label={`${label}${unreadCount ? `, ${unreadCount} unread` : ""}`}
        aria-haspopup="dialog"
        aria-expanded={expanded}
        aria-controls={mounted ? `${id}-panel` : undefined}
        onClick={() => (expanded ? close() : open())}
        className={`relative grid size-9 cursor-pointer place-items-center rounded-full text-foreground shadow-[inset_0_0_0_1px_var(--border)] transition-colors hover:bg-accent ${FOCUS}`}
      >
        <span ref={iconRef} className="grid origin-top place-items-center">
          <Bell className="size-4" strokeWidth={1.75} aria-hidden="true" />
        </span>
        <span
          aria-hidden="true"
          className="absolute -top-1 -right-1 inline-flex h-4 min-w-4 items-center justify-center rounded-full bg-primary px-1 text-[10px] font-medium text-primary-foreground tabular-nums shadow-[0_0_0_2px_var(--background)]"
          // Hidden while the inbox is open: the count is in the Unread tab then.
          style={{
            transform: unreadCount && !mounted ? "scale(1)" : "scale(0)",
            transition: reduced
              ? "none"
              : `transform 380ms ${unreadCount && !mounted ? "cubic-bezier(0.34,1.36,0.64,1)" : EASE}`,
          }}
        >
          <NumberRoll value={Math.min(99, unreadCount || 1)} />
        </span>
      </button>

      {mounted && (
        <div
          id={`${id}-panel`}
          role="dialog"
          aria-label={label}
          className="absolute top-0 z-40 overflow-hidden bg-popover text-popover-foreground"
          style={{
            [align === "end" ? "right" : "left"]: expanded
              ? align === "end"
                ? -fit.shift
                : fit.shift
              : 0,
            width,
            height,
            borderRadius: expanded ? 20 : 18,
            boxShadow: "inset 0 0 0 1px var(--border)",
            transition: reduced
              ? "none"
              : `width ${DURATION}ms ${EASE}, height ${DURATION}ms ${EASE}, right ${DURATION}ms ${EASE}, left ${DURATION}ms ${EASE}, border-radius ${DURATION}ms ${EASE}`,
          }}
        >
          {/* The bell, fading as its circle grows into the inbox. */}
          <span
            aria-hidden="true"
            className={`pointer-events-none absolute top-0 grid size-9 place-items-center ${align === "end" ? "right-0" : "left-0"}`}
            style={{
              opacity: expanded ? 0 : 1,
              transition: reduced
                ? "none"
                : `opacity ${expanded ? 140 : 260}ms ${EASE} ${expanded ? 0 : 140}ms`,
            }}
          >
            <Bell className="size-4" strokeWidth={1.75} />
          </span>

          <div
            ref={panelRef}
            inert={!expanded}
            className={`absolute top-0 ${align === "end" ? "right-0" : "left-0"}`}
            style={{
              width: fit.width,
              opacity: expanded ? 1 : 0,
              transition: reduced
                ? "none"
                : `opacity ${expanded ? 280 : 120}ms ${EASE} ${expanded ? 100 : 0}ms`,
            }}
          >
            <div className="flex items-center gap-2 px-3 pt-3 pb-2">
              <div
                role="tablist"
                aria-label={label}
                className="relative flex items-center gap-0.5"
              >
                <span
                  aria-hidden="true"
                  className="absolute top-0 left-0 h-7 rounded-full bg-accent shadow-[inset_0_0_0_1px_var(--border)]"
                  style={{
                    width: bar.width,
                    transform: `translateX(${bar.left}px)`,
                    transition:
                      bar.ready && !reduced
                        ? `transform 360ms ${EASE}, width 360ms ${EASE}`
                        : "none",
                  }}
                />
                {(["unread", "all"] as const).map((t) => (
                  <button
                    key={t}
                    ref={(el) => {
                      tabRefs.current[t] = el;
                    }}
                    role="tab"
                    aria-selected={tab === t}
                    tabIndex={tab === t ? 0 : -1}
                    onClick={() => setTab(t)}
                    onKeyDown={(e) => {
                      if (e.key !== "ArrowLeft" && e.key !== "ArrowRight")
                        return;
                      e.preventDefault();
                      const next = t === "unread" ? "all" : "unread";
                      setTab(next);
                      tabRefs.current[next]?.focus();
                    }}
                    className={`relative inline-flex h-7 cursor-pointer items-center gap-1.5 rounded-full px-3 text-[12.5px] font-medium transition-colors ${FOCUS} ${tab === t ? "text-foreground" : "text-muted-foreground hover:text-foreground"}`}
                  >
                    {t === "unread" ? "Unread" : "All"}
                    {t === "unread" && (
                      <span className="text-[11.5px] font-normal text-muted-foreground tabular-nums">
                        <NumberRoll value={unreadCount} />
                      </span>
                    )}
                  </button>
                ))}
              </div>
              <span className="ml-auto" />
              {onRead && (
                <StatusButton
                  size="sm"
                  variant="ghost"
                  status={markAll}
                  labels={{
                    idle: "Mark all read",
                    pending: "Marking",
                    success: "All read",
                    error: "Try again",
                  }}
                  onClick={readAll}
                  onReset={() => setMarkAll("idle")}
                  aria-disabled={
                    (!unreadCount && markAll === "idle") || undefined
                  }
                  className={
                    !unreadCount && markAll === "idle"
                      ? "pointer-events-none opacity-40"
                      : ""
                  }
                />
              )}
              <button
                type="button"
                aria-label={`Close ${label.toLowerCase()}`}
                onClick={() => close()}
                className={`grid size-7 shrink-0 cursor-pointer place-items-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
              >
                <X className="size-3.5" strokeWidth={1.75} aria-hidden="true" />
              </button>
            </div>

            <div
              className="max-h-[min(26rem,calc(100dvh_-_10rem))] overflow-y-auto overscroll-contain px-1.5 pb-1.5"
              role="tabpanel"
            >
              <div className="relative">
                <ul
                  ref={listRef}
                  aria-label={
                    tab === "unread"
                      ? "Unread notifications"
                      : "All notifications"
                  }
                  className="relative"
                >
                  {rows.map((r) =>
                    r.kind === "head" ? (
                      <li
                        key={r.key}
                        data-row-id={r.key}
                        aria-hidden="true"
                        className="px-3 pt-2 pb-1 text-[11px] font-medium text-muted-foreground"
                      >
                        {r.key.slice(5)}
                      </li>
                    ) : (
                      <Row
                        key={r.item.id}
                        item={r.item}
                        reduced={reduced}
                        canArchive={Boolean(onArchive)}
                        act={act}
                      />
                    ),
                  )}
                </ul>
                <div
                  ref={ghostRef}
                  aria-hidden="true"
                  className="pointer-events-none absolute inset-0"
                />
              </div>

              <div
                className="grid"
                style={{
                  gridTemplateRows: empty ? "1fr" : "0fr",
                  opacity: empty ? 1 : 0,
                  transition: reduced
                    ? "none"
                    : `grid-template-rows 420ms ${EASE}, opacity 300ms ${EASE} ${empty ? 120 : 0}ms`,
                }}
              >
                <div className="min-h-0 min-w-0 overflow-clip">
                  <div className="flex flex-col items-center gap-2 py-9 text-center">
                    <span className="grid size-9 place-items-center rounded-full text-emerald-600 shadow-[inset_0_0_0_1px_var(--border)] dark:text-emerald-400">
                      <svg
                        viewBox="0 0 16 16"
                        fill="none"
                        aria-hidden="true"
                        className="size-4"
                      >
                        <path
                          d="M3.5 8.5 6.5 11.5 12.5 4.5"
                          stroke="currentColor"
                          strokeWidth="1.8"
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          pathLength={1}
                          strokeDasharray={1}
                          style={{
                            strokeDashoffset: empty && expanded ? 0 : 1,
                            transition: reduced
                              ? "none"
                              : `stroke-dashoffset 480ms ${EASE} 260ms`,
                          }}
                        />
                      </svg>
                    </span>
                    <p className="text-[13px] font-medium">
                      {tab === "unread"
                        ? "You're all caught up"
                        : "Nothing here yet"}
                    </p>
                    <p className="text-[12px] text-muted-foreground">
                      {tab === "unread"
                        ? "New notifications will show up here."
                        : "When something happens, you'll hear about it here."}
                    </p>
                  </div>
                </div>
              </div>

              {loadMore && !noMore && tab === "all" && !empty && (
                <div className="flex justify-center py-1.5">
                  <button
                    type="button"
                    onClick={more}
                    aria-busy={loading || undefined}
                    className={`h-7 cursor-pointer rounded-full px-3 text-[12px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
                  >
                    <TextMorph>{loading ? "Loading" : "Show older"}</TextMorph>
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      <span className="sr-only" role="status">
        {announce}
      </span>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * RELATIVE TIME: "2 min ago" that keeps itself true
 *
 *   tick      it re-renders only when the words would change:
 *             on the next minute under an hour, the next hour
 *             under a day; nothing runs between
 *   roll      the number rolls up ("2 min" → "3 min") and the
 *             unit morphs when it changes ("59 min" → "1 h")
 *   date      past a week it settles on the date ("12 Sep")
 *
 * Until it's mounted it renders the date, so the server and the
 * first paint agree; the hover title is always the full time.
 * ───────────────────────────────────────────────────────── */

export type DateLike = Date | string | number;

export interface RelativeTimeProps extends Omit<
  React.HTMLAttributes<HTMLElement>,
  "children"
> {
  date: DateLike;
  /** Said before the time, e.g. "Last used". */
  prefix?: string;
  /** Under a minute. */
  justNow?: string;
  locales?: string | string[];
}

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

export const toTime = (d: DateLike) =>
  d instanceof Date
    ? d.getTime()
    : typeof d === "number"
      ? d
      : new Date(d).getTime();

const MONTHS = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
];

/** "12 Sep", with the year when it isn't this one; pass locales to use the browser's own format. */
export function formatDate(d: DateLike, locales?: string | string[]) {
  const t = new Date(toTime(d));
  const sameYear = t.getFullYear() === new Date().getFullYear();
  if (locales)
    return t.toLocaleDateString(
      locales,
      sameYear
        ? { day: "numeric", month: "short" }
        : { day: "numeric", month: "short", year: "numeric" },
    );
  return `${t.getDate()} ${MONTHS[t.getMonth()]}${sameYear ? "" : ` ${t.getFullYear()}`}`;
}

type Parts = { n: number | null; unit: string; next: number };

function parts(
  at: number,
  now: number,
  justNow: string,
  locales?: string | string[],
): Parts {
  const ago = Math.max(0, now - at);
  if (ago < MINUTE) return { n: null, unit: justNow, next: MINUTE - ago };
  if (ago < HOUR)
    return {
      n: Math.floor(ago / MINUTE),
      unit: "min ago",
      next: MINUTE - (ago % MINUTE),
    };
  if (ago < DAY) {
    const h = Math.floor(ago / HOUR);
    return {
      n: h,
      unit: h === 1 ? "hour ago" : "hours ago",
      next: HOUR - (ago % HOUR),
    };
  }
  if (ago < 7 * DAY) {
    const d = Math.floor(ago / DAY);
    return {
      n: d,
      unit: d === 1 ? "day ago" : "days ago",
      next: DAY - (ago % DAY),
    };
  }
  return { n: null, unit: formatDate(at, locales), next: 0 };
}

const subscribeMounted = () => () => {};

export function RelativeTime({
  date,
  prefix,
  justNow = "just now",
  locales,
  className = "",
  ...props
}: RelativeTimeProps) {
  const at = toTime(date);
  const mounted = React.useSyncExternalStore(
    subscribeMounted,
    () => true,
    () => false,
  );
  const [now, setNow] = React.useState(() => Date.now());
  const p = parts(at, mounted ? now : at + 8 * DAY, justNow, locales);

  // One timer, set for the moment the words change.
  React.useEffect(() => {
    if (!mounted || !p.next) return;
    const timer = window.setTimeout(() => setNow(Date.now()), p.next + 50);
    return () => window.clearTimeout(timer);
  }, [mounted, p.next, now]);

  React.useEffect(() => {
    const timer = window.setTimeout(() => setNow(Date.now()), 0);
    return () => window.clearTimeout(timer);
  }, [at]);

  const iso = new Date(at).toISOString();
  return (
    <time
      dateTime={iso}
      title={new Date(at).toLocaleString(locales ?? "en-GB", {
        dateStyle: "medium",
        timeStyle: "short",
      })}
      className={`inline-flex items-baseline whitespace-nowrap tabular-nums ${className}`}
      {...props}
    >
      {prefix && <span>{prefix}&nbsp;</span>}
      {/* Remounted once on the client, so the first real words appear without a morph. */}
      <Words key={mounted ? "client" : "server"} n={p.n} unit={p.unit} />
    </time>
  );
}

function Words({ n, unit }: { n: number | null; unit: string }) {
  return (
    <>
      <span
        aria-hidden={n === null || undefined}
        className="inline-grid transition-[grid-template-columns] duration-[380ms] ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:transition-none"
        style={{ gridTemplateColumns: n === null ? "0fr" : "1fr" }}
      >
        <span className="min-w-0 [clip-path:inset(-4px_0)]">
          <span className="inline-flex items-baseline pr-[0.25em]">
            <NumberRoll value={n ?? 1} direction="up" />
          </span>
        </span>
      </span>
      <TextMorph>{unit}</TextMorph>
    </>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * STATUS BUTTON: a button that tells you what happened
 *
 *   idle     "Save", with an optional icon
 *   pending  a spinner opens in; the label morphs to "Saving"
 *   success  a check draws itself; "Saved"
 *   error    the button gives a small shake; "Try again"
 *
 * Every change is one motion: the icon slot opens and closes,
 * icons swap through a blur, letters the labels share stay put
 * and the button's width eases to fit.
 * ───────────────────────────────────────────────────────── */

export type ActionStatus = "idle" | "pending" | "success" | "error";

export interface StatusButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  status?: ActionStatus;
  /** Labels per state; defaults to Save, Saving, Saved, Try again. */
  labels?: Partial<Record<ActionStatus, string>>;
  /** Shown before the label while idle. */
  icon?: React.ReactNode;
  variant?: "primary" | "outline" | "ghost";
  /** "sm" is 28px tall, for toolbars and headers. */
  size?: "default" | "sm";
  /** Called this long after success (ms), e.g. to go back to idle. */
  onReset?: () => void;
  resetAfter?: number;
}

const LABELS: Record<ActionStatus, string> = {
  idle: "Save",
  pending: "Saving",
  success: "Saved",
  error: "Try again",
};
const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${EASE} 120ms`
              : "none",
        }}
      />
    </svg>
  );
}

function Alert() {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="1" fill="currentColor" />
    </svg>
  );
}

export function StatusButton({
  status = "idle",
  labels,
  icon,
  variant = "primary",
  size = "default",
  onReset,
  resetAfter = 1800,
  className = "",
  onClick,
  ...props
}: StatusButtonProps) {
  const reduced = useReducedMotion();
  const ref = React.useRef<HTMLButtonElement>(null);
  const label = { ...LABELS, ...labels }[status];
  const showIcon = status !== "idle" || Boolean(icon);
  const busy = status === "pending";
  const sm = size === "sm";
  const iconSize = sm ? 14 : 16;

  // A short shake when it fails: the eye catches it even if you looked away.
  React.useEffect(() => {
    if (status !== "error" || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [status, reduced]);

  React.useEffect(() => {
    if (status !== "success" || !onReset) return;
    const timer = window.setTimeout(onReset, resetAfter);
    return () => window.clearTimeout(timer);
  }, [status, onReset, resetAfter]);

  const tone =
    status === "error"
      ? "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400"
      : variant === "primary"
        ? "bg-primary text-primary-foreground hover:bg-primary/90"
        : variant === "ghost"
          ? `hover:bg-accent hover:text-foreground ${status === "idle" ? "text-muted-foreground" : "text-foreground"}`
          : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent";

  const icons: Record<ActionStatus, React.ReactNode> = {
    idle: icon,
    // Spins only while pending, so a hidden spinner never keeps the page busy.
    pending: (
      <span
        className={`${sm ? "size-3" : "size-3.5"} rounded-full border-[1.5px] border-current border-t-transparent opacity-80 motion-reduce:animate-none ${status === "pending" ? "animate-spin" : ""}`}
      />
    ),
    success: <Check drawn={status === "success"} reduced={reduced} />,
    error: <Alert />,
  };

  return (
    <>
      <button
        ref={ref}
        type="button"
        aria-busy={busy || undefined}
        aria-disabled={busy || undefined}
        onClick={(e) => {
          if (busy) return e.preventDefault();
          onClick?.(e);
        }}
        className={`cursor-pointer disabled:cursor-default aria-disabled:cursor-default inline-flex items-center justify-center whitespace-nowrap rounded-full font-medium transition-[background-color,color,box-shadow,scale,padding] duration-300 active:scale-[0.97] motion-reduce:active:scale-100 ${
          sm
            ? `h-7 text-[12px] ${variant === "ghost" ? "px-2.5" : "px-3"}`
            : "h-9 px-4 text-[13px]"
        } ${FOCUS} ${tone} ${className}`}
        {...props}
      >
        <span
          aria-hidden="true"
          className={`relative flex shrink-0 items-center justify-center ${sm ? "h-3.5 [&_svg]:size-3.5" : "h-4 [&_svg]:size-4"}`}
          style={{
            width: showIcon ? iconSize : 0,
            marginRight: showIcon ? (sm ? 5 : 6) : 0,
            transition: reduced
              ? "none"
              : `width 380ms ${EASE}, margin 380ms ${EASE}`,
          }}
        >
          {(Object.keys(icons) as ActionStatus[]).map((s) => (
            <span
              key={s}
              className="absolute inset-0 flex items-center justify-center"
              style={{
                opacity: s === status ? 1 : 0,
                transform: s === status ? "none" : "scale(0.6)",
                filter: s === status ? "none" : "blur(3px)",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, transform 380ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              {icons[s]}
            </span>
          ))}
        </span>
        <TextMorph>{label}</TextMorph>
      </button>
      {/* Outside the button, so the announcement isn't read as part of its name. */}
      <span className="sr-only" role="status">
        {status === "idle" ? "" : label}
      </span>
    </>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * ROW MOTION: rows that keep their place on screen
 *
 *   glide     after any render (a sort, a filter, new data from
 *             the server) every row that moved glides from its
 *             old place to its new one. Glides are additive, so
 *             a change that lands mid-glide adds its own offset
 *             instead of restarting anything
 *   travel    a row that sorts onto the page slides in from the
 *             side where it ranked before; one that sorts off
 *             slides out toward its new rank
 *   enter     a row that's new to the list fades in where it
 *             lands while the rows below glide clear of it
 *   leave     a row that's gone folds away where it stood. Its
 *             copy is the row's own element, detached by React
 *             and moved into a layer React never renders into,
 *             so a leaving row costs no render at all
 *   stagger   a sort can ask for the rows to set off one after
 *             another, top first
 *
 * Positions are layout offsets (transforms ignored), kept after
 * every render and whenever the list changes size (a row
 * opening its detail), so they're never stale. Rows are found
 * by data-row-id; ranks are their places in the whole sorted
 * list, not just the page.
 * ───────────────────────────────────────────────────────── */

type Seen = { top: number; height: number; el: HTMLElement };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const GLIDE = 480;

export function useRowMotion(
  container: React.RefObject<HTMLElement | null>,
  {
    reduced,
    resetKey,
    ranks,
    ghosts,
  }: {
    reduced: boolean;
    resetKey?: string | number;
    ranks: ReadonlyMap<string, number>;
    ghosts: React.RefObject<HTMLElement | null>;
  },
) {
  const seen = React.useRef(new Map<string, Seen>());
  const lastRanks = React.useRef(ranks);
  const lastKey = React.useRef(resetKey);
  const staggerNext = React.useRef(false);

  const read = React.useCallback(() => {
    const out = new Map<string, Seen>();
    container.current
      ?.querySelectorAll<HTMLElement>("[data-row-id]")
      .forEach((el) =>
        out.set(el.dataset.rowId!, {
          top: el.offsetTop,
          height: el.offsetHeight,
          el,
        }),
      );
    return out;
  }, [container]);

  /** The row React just removed, back on screen where it stood, leaving: sliding toward where it went, or folding. */
  const leave = (was: Seen, dy: number) => {
    const layer = ghosts.current;
    const el = was.el;
    if (!layer || el.isConnected) return;
    // No getAnimations() here (it flushes style for the whole page): the exit below is added last and replaces any
    // glide still on the element.
    el.removeAttribute("data-row-id");
    el.removeAttribute("tabindex");
    el.setAttribute("aria-hidden", "true");
    el.inert = true;
    Object.assign(el.style, {
      position: "absolute",
      left: "0",
      right: "0",
      top: `${was.top}px`,
      height: `${was.height}px`,
      margin: "0",
      overflow: "hidden",
    });
    layer.appendChild(el);
    const a = el.animate(
      dy
        ? [
            { transform: "translateY(0px)", opacity: 1, filter: "blur(0px)" },
            {
              transform: `translateY(${dy}px)`,
              opacity: 0,
              filter: "blur(3px)",
            },
          ]
        : [
            { opacity: 1, transform: "none", filter: "blur(0px)" },
            { opacity: 0, transform: "scale(0.985)", filter: "blur(4px)" },
          ],
      { duration: dy ? 360 : 280, easing: EASE, fill: "forwards" },
    );
    a.onfinish = a.oncancel = () => el.remove();
  };

  React.useLayoutEffect(() => {
    const el = container.current;
    if (!el) return;
    const before = seen.current;
    const after = read();
    const prevRanks = lastRanks.current;
    seen.current = after;
    lastRanks.current = ranks;
    const stagger = staggerNext.current;
    staggerNext.current = false;
    if (lastKey.current !== resetKey) {
      // A different page: the caller slides the whole body; nothing glides and nothing folds.
      lastKey.current = resetKey;
      return;
    }
    if (reduced || !before.size) return;

    // A typical row's height. Rows that come onto or leave the page only hint at the way they went (a row and a
    // quarter at most), so the list never shows holes while they travel.
    const heights = [...after.values()]
      .map((b) => b.height)
      .sort((a, b) => a - b);
    const rowH = heights[Math.floor(heights.length / 2)] ?? 48;
    const clamp = (dy: number) =>
      Math.max(-rowH * 1.25, Math.min(rowH * 1.25, dy));

    let order = 0;
    after.forEach((now, id) => {
      const row = now.el;
      const was = before.get(id);
      const delay = stagger ? Math.min(order++ * 16, 200) : 0;
      if (was) {
        const dy = was.top - now.top;
        if (Math.abs(dy) < 0.5) return;
        row.animate(
          [
            { transform: `translateY(${dy}px)`, zIndex: 1 },
            { transform: "translateY(0px)", zIndex: 1 },
          ],
          {
            duration: GLIDE,
            delay,
            easing: EASE,
            composite: "add",
            fill: "backwards",
          },
        );
        return;
      }
      const from = prevRanks.get(id);
      const to = ranks.get(id);
      if (from !== undefined && to !== undefined) {
        // It ranked somewhere off the page: it comes in from that side.
        row.animate(
          [
            {
              transform: `translateY(${clamp((from - to) * rowH)}px)`,
              opacity: 0,
              filter: "blur(3px)",
            },
            { transform: "translateY(0px)", opacity: 1, filter: "blur(0px)" },
          ],
          {
            duration: GLIDE,
            delay: delay / 2,
            easing: EASE,
            fill: "backwards",
          },
        );
        return;
      }
      row.animate(
        [
          { opacity: 0, filter: "blur(4px)" },
          { opacity: 1, filter: "blur(0px)" },
        ],
        { duration: 420, delay: 90, easing: EASE, fill: "backwards" },
      );
    });

    // Still in the list, just not on this page: its copy slides toward where it went. Gone for good: it folds.
    before.forEach((was, id) => {
      if (after.has(id)) return;
      const from = prevRanks.get(id);
      const to = ranks.get(id);
      leave(
        was,
        from !== undefined && to !== undefined
          ? clamp((to - from) * rowH) || rowH
          : 0,
      );
    });
  });

  // The list changed size without a render of ours (a detail opening by transition): keep the positions true.
  React.useEffect(() => {
    const el = container.current;
    if (!el) return;
    const observer = new ResizeObserver(() => {
      seen.current = read();
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, [container, read]);

  return {
    /** The next change (a sort) sets the rows off one after another. */
    stagger: () => {
      staggerNext.current = true;
    },
  };
}

